// ─────────────────────────────────────────────────────────────
// LR03 — Nghiên cứu định tính
// ─────────────────────────────────────────────────────────────
export const LR03_QUIZ = {
  id: 'LR03-quiz-01',
  title: 'LR03 · Nghiên cứu định tính — Phỏng vấn, FG, NVivo',
  kind: 'quiz', subject: 'qualitative', difficulty: 3,
  skillsTrained: ['qualitative-research', 'interview', 'thematic-analysis'],
  questions: [
    { stem: '"Saturation" (bão hoà dữ liệu) trong NC định tính nghĩa là?', choices: ['Đạt cỡ mẫu thống kê đã tính trước', 'Phỏng vấn thêm không cho thêm chủ đề/insight mới — dấu hiệu dừng thu thập dữ liệu', 'Dùng nhiều phương pháp để kiểm chứng', 'Người tham gia trả lời lặp lại y nguyên'], answer: 1, explanation: 'Theoretical saturation (Glaser & Strauss) — khi phỏng vấn bổ sung không sinh code/theme mới thì dừng. Thông thường 12-15 PV sâu là đủ cho 1 nhóm tương đối đồng nhất (Guest 2006).' },
    { stem: 'Phương pháp lấy mẫu "snowball" phù hợp nhất khi?', choices: ['Có khung lấy mẫu (sampling frame) hoàn chỉnh', 'Đối tượng khó tiếp cận (ví dụ: người dùng ma tuý, NVYT làm phá thai bí mật) — nhờ người trong cuộc giới thiệu', 'Cần tính đại diện thống kê', 'Khảo sát toàn dân số trên 1 triệu'], answer: 1, explanation: 'Snowball/chain-referral phù hợp với hidden/hard-to-reach populations. Hạn chế: thiên lệch mạng lưới xã hội, không tổng quát hoá.' },
    { stem: 'Số người tham gia tiêu chuẩn cho 1 focus group dược?', choices: ['2-3 người', '6-10 người, đồng nhất về 1 đặc điểm cốt lõi (ví dụ: cùng nghề DSĐH)', '20-30 người', 'Càng đông càng tốt'], answer: 1, explanation: 'Krueger & Casey: FG tốt nhất 6-10 người, đủ đa dạng ý kiến nhưng vẫn cho mỗi người nói. Mini-FG 4-6 cho chủ đề nhạy cảm. Cần đồng nhất 1 trục để tạo an toàn tâm lý.' },
    { stem: 'Thematic analysis (Braun & Clarke 2006) có bao nhiêu bước?', choices: ['3 bước', '6 bước: làm quen dữ liệu → code → tìm theme → xem lại theme → đặt tên/định nghĩa → viết báo cáo', '10 bước', 'Không cố định, do nhà NC quyết'], answer: 1, explanation: '6 phases: Familiarization → Generating initial codes → Searching for themes → Reviewing themes → Defining and naming themes → Producing the report. Đây là phương pháp linh hoạt, không bám 1 trường phái lý thuyết.' },
    { stem: 'Phần mềm nào KHÔNG phải QDAS (Qualitative Data Analysis Software)?', choices: ['NVivo', 'ATLAS.ti', 'MAXQDA', 'SPSS'], answer: 3, explanation: 'NVivo, ATLAS.ti, MAXQDA, Dedoose là QDAS phổ biến cho coding định tính. SPSS, Stata, R là phần mềm thống kê định lượng.' },
    { stem: 'Trong NC định tính, "reflexivity" là?', choices: ['Lặp lại nghiên cứu để kiểm tra', 'Sự tự phản tỉnh của nhà NC về cách vị trí xã hội, định kiến và quan hệ của mình có thể ảnh hưởng dữ liệu và diễn giải', 'Thời gian phản ứng của người tham gia', 'Phân tích thống kê hồi cứu'], answer: 1, explanation: 'Reflexivity là chuẩn chất lượng quan trọng — nhà NC phải ghi audit trail, viết reflexive memo về vai trò bản thân (insider/outsider, power dynamics) ảnh hưởng dữ liệu thế nào.' },
    { stem: 'Để tăng độ tin cậy (trustworthiness — Lincoln & Guba), nhà NC định tính có thể dùng?', choices: ['Tính p-value', 'Triangulation (nhiều nguồn/phương pháp), member checking (cho người tham gia xem lại diễn giải), audit trail', 'Cronbach alpha', 'Bonferroni correction'], answer: 1, explanation: 'Lincoln & Guba 4 tiêu chí: credibility (triangulation, member checking, prolonged engagement), transferability (thick description), dependability (audit trail), confirmability (reflexivity). Không dùng p-value.' },
    { stem: 'Khi mã hoá dữ liệu (coding) lần đầu trong grounded theory, nên dùng?', choices: ['Axial coding ngay', 'Open coding — gán mã ngắn cho từng đoạn dữ liệu, sát ngôn ngữ người tham gia (in vivo codes)', 'Selective coding ngay', 'Bỏ qua giai đoạn mã, đi vào theme luôn'], answer: 1, explanation: 'Strauss & Corbin: open coding → axial coding (nhóm code liên quan) → selective coding (xoay quanh core category). In vivo code dùng nguyên từ của người tham gia, giữ ý nghĩa gốc.' },
    { stem: 'Một nghiên cứu PV sâu 20 dược sĩ về rào cản tư vấn OTC. Để bảo vệ đạo đức, BẮT BUỘC?', choices: ['Đăng tên thật vào báo cáo để minh bạch', 'Có chấp thuận đạo đức (IRB) + phiếu đồng thuận có chữ ký + ẩn danh dữ liệu (pseudonym hoặc mã hoá)', 'Chỉ cần lời nói đồng ý', 'Ghi âm bí mật để dữ liệu tự nhiên'], answer: 1, explanation: 'Helsinki Declaration + ICH GCP: IRB approval, informed consent có chữ ký, ẩn danh hoặc khử định danh dữ liệu, quyền rút lui bất kỳ lúc nào. Ghi âm bí mật vi phạm đạo đức.' },
    { stem: 'Sự khác biệt cốt lõi giữa NC định tính và định lượng?', choices: ['Định tính chỉ nghiên cứu trên mẫu nhỏ, định lượng trên mẫu lớn', 'Định tính tìm hiểu ý nghĩa, trải nghiệm, ngữ cảnh (how/why) — định lượng đo lường biến số, mối quan hệ thống kê (what/how much)', 'Định tính không cần đạo đức', 'Định lượng luôn tốt hơn'], answer: 1, explanation: 'Định tính (qualitative) trả lời câu hỏi why/how — diễn giải. Định lượng (quantitative) đo lường, kiểm định giả thuyết. Mixed methods kết hợp cả hai.' },
  ],
};

// ─────────────────────────────────────────────────────────────
// LR04 — RCT, Cohort, Case-control
// ─────────────────────────────────────────────────────────────
export const LR04_QUIZ = {
  id: 'LR04-quiz-01',
  title: 'LR04 · NC định lượng — RCT, Cohort, Case-control',
  kind: 'quiz', subject: 'quantitative', difficulty: 4,
  skillsTrained: ['rct', 'cohort', 'case-control', 'epidemiology'],
  questions: [
    { stem: 'Mục đích chính của randomization (phân ngẫu nhiên) trong RCT?', choices: ['Tăng cỡ mẫu', 'Cân bằng các yếu tố gây nhiễu (cả đã biết và chưa biết) giữa 2 nhóm — nền tảng để suy luận nhân quả', 'Bảo đảm người tham gia mù', 'Giảm chi phí'], answer: 1, explanation: 'Randomization → các biến nhiễu đo và không đo được phân phối đều ngẫu nhiên giữa 2 nhóm. Đây là điểm phân biệt RCT với NC quan sát. Không phải để giảm cỡ mẫu.' },
    { stem: 'Trong RCT mù đôi (double-blind), AI bị mù?', choices: ['Chỉ người tham gia', 'Chỉ điều tra viên', 'Cả người tham gia và điều tra viên/đánh giá viên đều không biết phân nhóm', 'Cả sponsor cũng bị mù'], answer: 2, explanation: 'Double-blind: participant + investigator/outcome assessor. Triple-blind thêm data analyst. Mù để giảm bias kỳ vọng (placebo, Hawthorne, đánh giá chủ quan).' },
    { stem: 'Phân tích ITT (Intention-to-Treat) nghĩa là?', choices: ['Phân tích chỉ những người hoàn thành điều trị đúng phác đồ (per-protocol)', 'Phân tích theo nhóm phân ngẫu nhiên ban đầu, bất kể họ có tuân thủ hay đổi nhóm — bảo toàn tính ngẫu nhiên', 'Phân tích chỉ những ai có biến cố', 'Phân tích sau khi loại người bỏ cuộc'], answer: 1, explanation: 'ITT phân tích "once randomized, always analyzed" — bảo vệ tính ngẫu nhiên, ước tính hiệu quả thực dụng (effectiveness). Per-protocol ước tính hiệu lực (efficacy) nhưng có thể bias do non-random dropout.' },
    { stem: 'Một RCT thử nghiệm thuốc mới với tỉ lệ bỏ cuộc 40%. Vấn đề chính?', choices: ['Cỡ mẫu quá lớn', 'Attrition bias (mất theo dõi) — có thể làm sai lệch kết quả nếu lý do bỏ cuộc liên quan đến điều trị/kết cục; CONSORT khuyến nghị dropout < 20%', 'Cần tăng liều', 'Không thấy ý nghĩa lâm sàng'], answer: 1, explanation: 'Dropout cao đe doạ tính giá trị nội tại. CONSORT 2010: báo cáo lý do và số bỏ cuộc theo nhóm; phân tích nhạy (sensitivity) với LOCF, multiple imputation. Dropout > 20% là red flag.' },
    { stem: 'Khác biệt cốt lõi giữa nghiên cứu cohort tiến cứu (prospective) và hồi cứu (retrospective)?', choices: ['Tiến cứu rẻ hơn', 'Prospective: định nghĩa cohort khi chưa xảy ra biến cố, theo dõi tiến lên → ít recall bias, đo lường chuẩn hoá. Retrospective: xác định cohort dựa trên hồ sơ sẵn có khi biến cố đã xảy ra', 'Hồi cứu luôn chính xác hơn', 'Tiến cứu không cần follow-up'], answer: 1, explanation: 'Prospective cohort thiết kế đo lường trước → kiểm soát chất lượng dữ liệu tốt, tốn thời gian/tiền. Retrospective dùng dữ liệu sẵn có → nhanh/rẻ nhưng phụ thuộc chất lượng hồ sơ.' },
    { stem: 'Nghiên cứu case-control phù hợp nhất cho?', choices: ['Bệnh cực kỳ hiếm (incidence < 1/10.000) hoặc thời gian latent dài', 'Bệnh phổ biến', 'Thuốc đã được duyệt 1 năm', 'Đánh giá tác dụng cấp tính'], answer: 0, explanation: 'Case-control hiệu quả với bệnh hiếm vì lấy có ca → tìm phơi nhiễm. Vd: hội chứng Reye + aspirin trẻ em, vaginal clear cell carcinoma + DES. Hạn chế: recall bias, không tính incidence trực tiếp.' },
    { stem: 'Trong case-control, "matching" (ghép cặp) theo tuổi/giới có mục đích gì?', choices: ['Tăng cỡ mẫu', 'Loại trừ yếu tố nhiễu đã biết (tuổi, giới...) bằng cách bảo đảm ca và chứng tương đương ở các biến đó', 'Tăng độ chính xác chẩn đoán', 'Giảm thời gian'], answer: 1, explanation: 'Matching kiểm soát confounder ngay từ thiết kế. Khi đã match, phải phân tích bằng conditional logistic regression (McNemar cho dữ liệu cặp), không thể đánh giá tác động của biến đã match.' },
    { stem: 'Số đo lường nguy cơ phù hợp nhất trong cohort study?', choices: ['Odds Ratio (OR)', 'Relative Risk (RR) hoặc Hazard Ratio (HR) — vì có thể tính incidence trong cohort', 'Prevalence Ratio', 'Mean difference'], answer: 1, explanation: 'Cohort cho phép tính incidence → RR = risk(exposed)/risk(unexposed). Với time-to-event dùng HR (Cox model). Case-control dùng OR (xấp xỉ RR khi bệnh hiếm <10%).' },
    { stem: 'Cỡ mẫu cho RCT phụ thuộc vào?', choices: ['Chỉ alpha và beta', 'Alpha (sai lầm I, thường 0.05), beta (sai lầm II, 0.2 → power 80%), effect size (delta) đã định trước, độ biến thiên', 'Chỉ effect size', 'Số trung tâm tham gia'], answer: 1, explanation: 'n phụ thuộc α (mức tin cậy), 1-β (power, thường 0.8 hoặc 0.9), effect size mong đợi (MCID — minimal clinically important difference) và σ. Thường thêm 10-20% bù dropout.' },
    { stem: 'Để minh bạch hoá RCT, hướng dẫn báo cáo chuẩn quốc tế là?', choices: ['STROBE', 'CONSORT 2010 + đăng ký trước trên ClinicalTrials.gov hoặc WHO ICTRP', 'PRISMA', 'STARD'], answer: 1, explanation: 'CONSORT cho RCT, STROBE cho NC quan sát, PRISMA cho SR/MA, STARD cho NC chẩn đoán. ICMJE yêu cầu đăng ký trial trước khi tuyển BN đầu tiên.' },
  ],
};

// ─────────────────────────────────────────────────────────────
// LR05 — Systematic Review + Meta-analysis
// ─────────────────────────────────────────────────────────────
export const LR05_QUIZ = {
  id: 'LR05-quiz-01',
  title: 'LR05 · Systematic Review + Meta-analysis — PRISMA, Cochrane',
  kind: 'quiz', subject: 'sr-ma', difficulty: 4,
  skillsTrained: ['systematic-review', 'meta-analysis', 'critical-appraisal'],
  questions: [
    { stem: 'PRISMA 2020 là?', choices: ['Một phần mềm meta-analysis', 'Hướng dẫn báo cáo (reporting guideline) cho systematic review và meta-analysis — 27 mục checklist + sơ đồ flow', 'Tiêu chí lựa chọn nghiên cứu', 'Công cụ đánh giá nguy cơ thiên lệch'], answer: 1, explanation: 'PRISMA 2020 (Page et al. BMJ 2021) — bản cập nhật từ PRISMA 2009, có 27 items + 4 phụ lục + flow diagram. Bắt buộc cho hầu hết tạp chí Y khoa khi đăng SR/MA.' },
    { stem: 'PICO trong câu hỏi SR là?', choices: ['Population/Patient — Intervention — Comparator — Outcome', 'Probability — Incidence — Confidence — Odds', 'Plan — Implement — Check — Outcome', 'Primary — Initial — Continuous — Original'], answer: 0, explanation: 'PICO định khung câu hỏi (vd: ở BN ĐTĐ type 2 [P], SGLT2 inhibitor [I] so với GLP-1 RA [C], có giảm MACE [O] không?). Mở rộng PICOS thêm Study design, PICOTS thêm Timeframe và Setting.' },
    { stem: 'Công cụ Cochrane RoB 2 (Risk of Bias 2) dùng cho?', choices: ['Đánh giá nguy cơ thiên lệch trong RCT — 5 domain (randomization, deviations from intended interventions, missing outcome data, measurement of outcome, selection of reported result)', 'Đánh giá NC quan sát', 'Đánh giá chất lượng tạp chí', 'Đánh giá meta-bias'], answer: 0, explanation: 'RoB 2 (Sterne 2019) thay thế bản 2008. 5 domain với signaling questions → Low/Some concerns/High. Cho NC quan sát dùng ROBINS-I, NC chẩn đoán dùng QUADAS-2.' },
    { stem: 'Chỉ số I² trong meta-analysis đo lường?', choices: ['Hiệu quả điều trị tuyệt đối', 'Tính không đồng nhất (heterogeneity) — % phương sai do khác biệt thực sự giữa NC, không do tình cờ. >50% là đáng kể, >75% là cao', 'Sai số chuẩn của trung bình', 'Tỉ lệ tử vong'], answer: 1, explanation: 'I² = (Q - df)/Q × 100%. <25% thấp, 25-50% trung bình, 50-75% đáng kể, >75% cao (Higgins 2003). Bổ sung τ² (tau-squared) ước tính phương sai giữa NC, và prediction interval.' },
    { stem: 'Khi I² cao (>75%), nên?', choices: ['Vẫn dùng fixed-effect model', 'Cân nhắc dùng random-effects model, đồng thời điều tra nguồn heterogeneity bằng phân tích nhóm con (subgroup), meta-regression hoặc xem có nên gộp không', 'Bỏ NC outlier', 'Tăng cỡ mẫu'], answer: 1, explanation: 'Random-effects (DerSimonian-Laird hoặc REML) phù hợp khi giả định effect khác nhau giữa NC. Nếu heterogeneity rất cao + không giải thích được → cân nhắc narrative synthesis thay vì pooled estimate.' },
    { stem: 'Forest plot biểu diễn?', choices: ['Phân bố tuổi BN', 'Effect size của từng NC kèm CI, kết hợp với diamond ước lượng tổng hợp và CI tổng', 'Sự khác biệt giữa intervention và comparator theo thời gian', 'Biểu đồ điểm scatter'], answer: 1, explanation: 'Forest plot — ô vuông tỉ lệ thuận với trọng số (weight), thanh ngang là CI95%, đường thẳng đứng là no-effect line (1 cho OR/RR, 0 cho MD/SMD). Diamond ở dưới là pooled estimate.' },
    { stem: 'Funnel plot bất đối xứng gợi ý?', choices: ['Heterogeneity cao', 'Publication bias (thiên lệch xuất bản) — NC âm tính/nhỏ ít được xuất bản, hoặc small-study effects', 'Effect size lớn', 'Power cao'], answer: 1, explanation: 'Funnel plot: effect (trục x) vs precision/SE (trục y). Khi không có bias → hình phễu cân đối. Asymmetry gợi ý publication bias nhưng cũng có thể do heterogeneity, small-study effect, chất lượng kém. Test: Egger\'s, Begg\'s.' },
    { stem: 'GRADE đánh giá chất lượng evidence theo 4 mức nào?', choices: ['A — B — C — D', 'High — Moderate — Low — Very low (dùng cho từng outcome, không phải toàn SR)', 'Strong — Weak', '1 — 2 — 3 — 4'], answer: 1, explanation: 'GRADE (Guyatt 2008) bắt đầu RCT = high, NC quan sát = low; có 5 yếu tố hạ bậc (RoB, inconsistency, indirectness, imprecision, publication bias) và 3 yếu tố nâng (large effect, dose-response, plausible confounders against effect).' },
    { stem: 'Số NC tối thiểu để thực hiện meta-analysis là?', choices: ['1', 'Tối thiểu 2 NC có dữ liệu so sánh được (Cochrane chấp nhận 2), nhưng ý nghĩa thống kê thường cần ≥ 5-10 và nên đánh giá heterogeneity cẩn thận', '5', '20'], answer: 1, explanation: 'Cochrane Handbook v6.4: có thể pool từ 2 NC. Tuy nhiên với <5 NC, ước tính τ² không tin cậy → nên dùng Hartung-Knapp adjustment hoặc Bayesian. Test publication bias (Egger) cần ≥ 10 NC.' },
    { stem: 'PROSPERO là?', choices: ['Phần mềm chạy meta-analysis', 'Cơ sở dữ liệu đăng ký đề cương systematic review trước khi thực hiện (NIHR/CRD York) — giúp giảm thiên lệch và trùng lặp', 'Tạp chí Cochrane', 'Công cụ trích xuất dữ liệu'], answer: 1, explanation: 'PROSPERO (crd.york.ac.uk/prospero) đăng ký miễn phí protocol SR. PRISMA-P là hướng dẫn viết protocol. Đăng ký giúp minh bạch và tránh trùng lặp đề tài.' },
  ],
};

