// LR10 — Pharmacoeconomics
// ─────────────────────────────────────────────────────────────
export const LR10_QUIZ = {
  id: 'LR10-quiz-01',
  title: 'LR10 · Pharmacoeconomics — CEA, CUA, CBA, ICER, QALY',
  kind: 'quiz', subject: 'pharmacoeconomics', difficulty: 4,
  skillsTrained: ['pharmacoeconomics', 'cost-effectiveness', 'health-economics'],
  questions: [
    { stem: '4 phương pháp đánh giá kinh tế dược chủ yếu là?', choices: ['CMA (Cost-Minimization), CEA (Cost-Effectiveness), CUA (Cost-Utility), CBA (Cost-Benefit)', 'PESTLE — SWOT — ROI — NPV', 'Markov — Monte Carlo — Decision tree — Tornado', 'GDP — PPP — HDI — Inflation'], answer: 0, explanation: 'CMA: giả định outcome bằng nhau → so chi phí. CEA: outcome đo lường tự nhiên (life-year, mmHg). CUA: outcome QALY → so sánh xuyên ngành. CBA: cả chi phí và outcome đều quy về tiền.' },
    { stem: 'QALY (Quality-Adjusted Life Year) tính bằng?', choices: ['Số năm sống × utility (0 = chết, 1 = khoẻ hoàn hảo)', 'Số ngày nhập viện', 'Số liều thuốc', 'Tổng chi phí'], answer: 0, explanation: 'QALY = sum(thời gian × utility trong giai đoạn đó). Vd: 5 năm với utility 0.8 = 4 QALY. Utility đo bằng EQ-5D-5L, SF-6D, hoặc TTO/SG. Cho phép so sánh chi phí-hiệu quả giữa các bệnh hoàn toàn khác nhau.' },
    { stem: 'ICER (Incremental Cost-Effectiveness Ratio) là?', choices: ['ICER = (Cost_A − Cost_B) / (Effect_A − Effect_B) — chi phí gia tăng để đạt thêm 1 đơn vị hiệu quả (vd: 1 QALY)', 'Chi phí tuyệt đối của can thiệp', 'Tổng QALY của BN', 'Hiệu quả trên chi phí trung bình'], answer: 0, explanation: 'ICER = ΔC/ΔE. Vd thuốc A 200tr/QALY so với thuốc B → mỗi QALY thêm cần 200tr. So với willingness-to-pay (WTP) threshold để quyết định cost-effective hay không.' },
    { stem: 'WHO khuyến nghị ngưỡng cost-effectiveness (WTP) là?', choices: ['Cố định 50.000 USD/QALY toàn thế giới', '≤ 1× GDP/capita: rất hiệu quả chi phí; 1-3× GDP/capita: hiệu quả chi phí; >3× GDP/capita: không hiệu quả chi phí (WHO-CHOICE, nhưng đang được đánh giá lại)', '100 triệu VND', 'Tuỳ ý'], answer: 1, explanation: 'Ngưỡng WHO-CHOICE cũ. VN GDP/capita ~4500 USD (2024) → ngưỡng 3× ~ 13.500 USD ~ 340 triệu VND/QALY. Tuy nhiên gần đây nhiều nước (Anh NICE £20-30k, Mỹ ~$100k-$150k/QALY) dùng ngưỡng riêng. Cải tiến: opportunity-cost-based threshold.' },
    { stem: 'Mô hình Markov trong pharmacoeconomic dùng để?', choices: ['Mô phỏng diễn tiến BN qua các trạng thái sức khoẻ (health states) theo chu kỳ thời gian (cycle), với xác suất chuyển trạng thái — phù hợp bệnh mạn tính', 'Tính cỡ mẫu', 'Đánh giá nguy cơ thiên lệch', 'Kiểm định t-test'], answer: 0, explanation: 'Markov model: states (healthy, diseased, dead) + transition probabilities + utility/cost mỗi state. Memoryless (xác suất chỉ phụ thuộc trạng thái hiện tại). Vd: HIV (no AIDS → AIDS → death). Bổ sung Monte Carlo simulation cho probabilistic sensitivity analysis (PSA).' },
    { stem: 'Khi 2 thuốc có hiệu quả tương đương đã chứng minh, đánh giá kinh tế phù hợp là?', choices: ['CUA', 'CMA (Cost-Minimization Analysis) — chỉ so chi phí; tuy nhiên equivalence phải được chứng minh nghiêm túc trước, nếu không nên dùng CEA/CUA', 'CBA', 'ICER'], answer: 1, explanation: 'CMA giả định outcome bằng nhau. Cẩn thận: "no significant difference" không đồng nghĩa "equivalent" (cần CI nằm trong margin equivalence). Nhiều chuyên gia khuyến khích luôn dùng CEA/CUA để có uncertainty quanh cả cost và effect.' },
    { stem: 'Sensitivity analysis trong PE để?', choices: ['Đánh giá ảnh hưởng của bất định các tham số đầu vào lên ICER — gồm one-way (tornado diagram), two-way, và probabilistic (PSA với CEAC)', 'Tăng cỡ mẫu', 'Loại bỏ outlier', 'Tính p-value'], answer: 0, explanation: 'PSA dùng phân phối xác suất cho tham số → simulate 10.000+ lần Monte Carlo → cost-effectiveness acceptability curve (CEAC) cho % can thiệp cost-effective ở mỗi WTP. Tornado cho thấy biến nào nhạy cảm nhất.' },
    { stem: 'Discount rate trong đánh giá kinh tế dược là?', choices: ['Lãi suất chiết khấu (3-5%) áp cho chi phí và outcome ở tương lai để quy về giá trị hiện tại — vì 1 đồng hôm nay > 1 đồng ngày mai, 1 QALY hôm nay > 1 QALY tương lai', 'Giá thuốc chiết khấu', 'Phí bảo hiểm', 'Lãi ngân hàng cá nhân'], answer: 0, explanation: 'NICE Anh dùng 3.5% cho cả cost và benefit. Mỹ ICER 3%. VN BYT đề xuất 3-5%. Discount cho chi phí hợp lý theo tài chính, nhưng discount QALY còn tranh cãi (vì sao QALY tương lai kém giá trị?).' },
    { stem: 'Perspective (góc nhìn) trong đánh giá kinh tế ảnh hưởng đến chi phí được tính?', choices: ['Không quan trọng', 'Quan trọng: payer/healthcare provider (chỉ chi phí trực tiếp y tế); societal (cộng cả productivity loss, informal care, transport); patient (out-of-pocket). Phải nêu rõ trong báo cáo', 'Chỉ có 1 góc nhìn duy nhất', 'Tuỳ tác giả'], answer: 1, explanation: 'CHEERS 2022 reporting guideline yêu cầu nêu rõ perspective. Societal perspective thường cho ICER thấp hơn (vì cộng thêm productivity gain). VN BYT khuyến nghị payer perspective cho quyết định bảo hiểm, societal cho chính sách công.' },
    { stem: 'Hướng dẫn báo cáo chuẩn cho NC pharmacoeconomic là?', choices: ['STROBE', 'CHEERS 2022 (Consolidated Health Economic Evaluation Reporting Standards)', 'CONSORT', 'PRISMA'], answer: 1, explanation: 'CHEERS 2022 (Husereau et al. Value Health 2022) — 28 items checklist. Bắt buộc với hầu hết tạp chí Health Economics. CHEERS cũ 2013 đã cập nhật để tích hợp PSA, model transparency, equity considerations.' },
  ],
};

